class Solution {
    int cnt = 0;
    public int findTargetSumWays(int[] nums, int target) {
        backtrack(nums,target,0);
        return cnt;
    }
    private void backtrack(int[] nums, int target, int index){
        if(index == nums.length){
            if(target == 0) cnt++;
            return;
        }
        backtrack(nums, target-nums[index], index+1);
        backtrack(nums, target+nums[index], index+1);
    }
}
